CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE instance_metadata (
  singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
  server_instance_id uuid NOT NULL DEFAULT gen_random_uuid(),
  data_epoch uuid NOT NULL DEFAULT gen_random_uuid(),
  key_check jsonb NOT NULL
);
CREATE TABLE owners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), singleton boolean UNIQUE NOT NULL DEFAULT true CHECK(singleton), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sync_heads (owner_id uuid PRIMARY KEY REFERENCES owners(id), cursor bigint NOT NULL DEFAULT 0, min_cursor bigint NOT NULL DEFAULT 0);
CREATE TABLE sync_events (owner_id uuid NOT NULL REFERENCES owners(id), cursor bigint NOT NULL, kind text NOT NULL, entity_id uuid NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,cursor));
CREATE TABLE devices (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES owners(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(owner_id,id));
CREATE TABLE device_sessions (id uuid PRIMARY KEY, owner_id uuid NOT NULL, device_id uuid NOT NULL, family_id uuid NOT NULL, access_hash text UNIQUE NOT NULL, refresh_hash text UNIQUE NOT NULL, access_expires_at timestamptz NOT NULL, refresh_expires_at timestamptz NOT NULL, rotated_at timestamptz, revoked_at timestamptz, FOREIGN KEY(owner_id,device_id) REFERENCES devices(owner_id,id));
CREATE TABLE pairing_codes (code_hash text PRIMARY KEY, owner_id uuid NOT NULL REFERENCES owners(id), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE pairing_attempts (ip_hash text PRIMARY KEY, window_start timestamptz NOT NULL, count integer NOT NULL);
CREATE TABLE provider_connections (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES owners(id), name text NOT NULL, base_url text NOT NULL, model text NOT NULL, context_window integer NOT NULL CHECK(context_window>=2048), max_output_tokens integer NOT NULL CHECK(max_output_tokens>0 AND max_output_tokens<context_window), credential jsonb NOT NULL, UNIQUE(owner_id,id));
CREATE TABLE worlds (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES owners(id), name text NOT NULL, revision integer NOT NULL DEFAULT 1, next_command bigint NOT NULL DEFAULT 0, UNIQUE(owner_id,id));
CREATE TABLE rooms (id uuid PRIMARY KEY, owner_id uuid NOT NULL, world_id uuid NOT NULL, name text NOT NULL, provider_id uuid NOT NULL, next_sequence bigint NOT NULL DEFAULT 0, FOREIGN KEY(owner_id,world_id) REFERENCES worlds(owner_id,id), FOREIGN KEY(owner_id,provider_id) REFERENCES provider_connections(owner_id,id), UNIQUE(owner_id,world_id,id), UNIQUE(owner_id,id));
CREATE TABLE runs (id uuid PRIMARY KEY, owner_id uuid NOT NULL, world_id uuid NOT NULL, room_id uuid NOT NULL, client_command_id uuid NOT NULL, request_hash text NOT NULL, user_message_id uuid NOT NULL, reply_message_id uuid NOT NULL, command_order bigint NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','completed','failed','cancelled','interrupted')), attempts integer NOT NULL DEFAULT 0, fence bigint, lease_holder uuid, error_code text, next_attempt_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(owner_id,world_id,room_id) REFERENCES rooms(owner_id,world_id,id), UNIQUE(owner_id,client_command_id), UNIQUE(world_id,command_order), UNIQUE(owner_id,id));
CREATE INDEX runs_recovery ON runs(state,next_attempt_at);
CREATE TABLE messages (id uuid PRIMARY KEY, owner_id uuid NOT NULL, room_id uuid NOT NULL, run_id uuid NOT NULL, sequence bigint NOT NULL, role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('accepted','streaming','completed','failed','cancelled','interrupted')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(owner_id,room_id) REFERENCES rooms(owner_id,id), FOREIGN KEY(owner_id,run_id) REFERENCES runs(owner_id,id), UNIQUE(room_id,sequence), UNIQUE(run_id,role));
CREATE TABLE world_leases (world_id uuid PRIMARY KEY REFERENCES worlds(id), holder uuid, run_id uuid REFERENCES runs(id), fencing_token bigint NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, run_id uuid NOT NULL, attempt integer NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), dispatched_at timestamptz, FOREIGN KEY(owner_id,run_id) REFERENCES runs(owner_id,id), UNIQUE(run_id,attempt));
CREATE TABLE usage_daily (owner_id uuid NOT NULL REFERENCES owners(id), day date NOT NULL, requests integer NOT NULL DEFAULT 0, PRIMARY KEY(owner_id,day));
CREATE TABLE usage_ledger (id uuid PRIMARY KEY, owner_id uuid NOT NULL, run_id uuid NOT NULL, attempt integer NOT NULL, state text NOT NULL CHECK(state IN ('reserved','known','unknown')), input_tokens integer, output_tokens integer, estimated_input_tokens integer NOT NULL, reserved_output_tokens integer NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(owner_id,run_id) REFERENCES runs(owner_id,id), UNIQUE(run_id,attempt));
